bool ValidateMemoryPointer(uintptr_t address, uintptr_t baseAddress, size_t expectedSize) {
    return (address >= baseAddress && address < baseAddress + expectedSize);
}

// Exemplo conceitual de validação de integridade
void PreValidateAndPostValidate(uint8_t* dest, uint32_t* destLen, const uint8_t* source, uint32_t sourceLen) {
    // 1. Valide se os ponteiros são válidos para este processo
    if (!ValidateMemoryPointer(reinterpret_cast<uintptr_t>(dest), 
                               reinterpret_cast<uintptr_t>(base_address_of_my_app), 
                               *destLen)) {
        return; // Fallback ou erro
    }

    // 2. Calcule hash inicial dos dados de fonte
    uint8_t initialHash[32] = {0};
    // Implemente cálculo de hash aqui usando apenas os bytes legítimos da 'source'

    // ... execute NormalUncompress ...

    // 3. Calcule hash final e compare
    uint8_t finalHash[32] = {0};
    // Calcule hash dos dados resultantes em 'dest'

    if (memcmp(initialHash, finalHash, sizeof(initialHash)) != 0) {
        // Dados foram corrompidos por um hook externo
        KeyManager::secure_clean(dest, *destLen);
        return -1;
